import { test } from "node:test";
import assert from "node:assert/strict";
import { LEVELS } from "../domain/nibbles/levels.js";

// Spec 047: generated by tools/nibblesLevels.mjs from the real level-sprite
// PNG (assets/games/nibbles/src/levels.png). These assertions are hand-
// derived from an independent read of the source pixels (recorded in this
// spec's own design.md), not merely re-deriving the extractor's own math -
// the point is to catch a wrong tile offset/color read, not to restate it.

test("there are exactly 30 levels", () => {
    assert.equal(LEVELS.length, 30);
});

test("level 1 has no walls at all", () => {
    const level = LEVELS[0];
    assert.deepEqual(level.cells, []);
    assert.deepEqual(level.colors, []);
    assert.deepEqual(level.start, { x: 36, y: 12 });
});

test("level 3 is two vertical bars, hand-verified against the source pixels", () => {
    const level = LEVELS[2];
    assert.deepEqual(level.start, { x: 36, y: 13 });
    assert.equal(level.cells.length, 44); // 11 rows (y=2..12) * 2 x-positions per side * 2 sides
    const xs = new Set(level.cells.map(([x]) => x));
    assert.deepEqual([...xs].sort((a, b) => a - b), [7, 8, 31, 32]);
    const ys = level.cells.map(([, y]) => y);
    assert.equal(Math.min(...ys), 2);
    assert.equal(Math.max(...ys), 12);
});

test("level 30 is a dense, multi-colored level", () => {
    const level = LEVELS[29];
    assert.deepEqual(level.start, { x: 38, y: 7 });
    assert.equal(level.cells.length, 318);
    assert.equal(level.colors.length, 4);
});

test("every level's own start point is in-bounds and not a wall", () => {
    for (let i = 0; i < LEVELS.length; i++) {
        const level = LEVELS[i];
        assert.ok(level.start.x >= 0 && level.start.x < 40, `level ${i + 1} start.x`);
        assert.ok(level.start.y >= 0 && level.start.y < 15, `level ${i + 1} start.y`);
        assert.ok(!level.cells.some(([x, y]) => x === level.start.x && y === level.start.y), `level ${i + 1} start is not a wall`);
    }
});

test("every wall cell's own color index points at a real entry in that level's own palette", () => {
    for (let i = 0; i < LEVELS.length; i++) {
        const level = LEVELS[i];
        for (const [, , colorIndex] of level.cells) {
            assert.ok(colorIndex >= 0 && colorIndex < level.colors.length, `level ${i + 1} color index ${colorIndex}`);
        }
    }
});
